import { AmenityKey } from './amenities';

export type Season = 'low' | 'mid' | 'midplus' | 'high';

export interface SeasonalRate {
  season: Season;
  label: string;
  perNight: number; // ZAR
}

export interface Unit {
  id: string;
  name: string;
  bedrooms: number;
  bathrooms: number;
  sleeps: number;
  rates: SeasonalRate[];
  amenities: AmenityKey[];
  description?: string;
  images: string[];
  minStay?: number;
  nightsbridgeUrl?: string;
  videoUrl?: string;        // YouTube embed URL (https://www.youtube.com/embed/ID)
  mapUrl?: string;          // Google Maps share URL
  notes?: string;
  bookingFee?: number;        // non-refundable, ZAR
  securityDeposit?: number;   // refundable, ZAR
}

export type ComplexCategory =
  | 'beachfront'
  | 'village'
  | 'resort'
  | 'luxury'
  | 'selfcatering';

export interface Complex {
  id: string;
  slug: string;
  name: string;
  tagline: string;
  location: string;
  category: ComplexCategory;
  featured: boolean;
  coverImage: string;
  units: Unit[];
  complexAmenities: AmenityKey[];
  description: string;
  highlights: string[];
}

