// Sort units within every complex numerically by trailing unit number
for (const complex of complexes) {
  complex.units.sort((a, b) => {
    // Extract the last numeric segment from the unit id (e.g. "breakers-128" → 128)
    const numA = parseInt(a.id.match(/(\d+)(?!.*\d)/)?.[1] ?? '0', 10);
    const numB = parseInt(b.id.match(/(\d+)(?!.*\d)/)?.[1] ?? '0', 10);
    return numA - numB;
  });
}

// Helper: get complex by slug
export function getComplexBySlug(slug: string): Complex | undefined {
  return complexes.find((c) => c.slug === slug);
}

// Helper: get featured complexes
export function getFeaturedComplexes(): Complex[] {
  return complexes.filter((c) => c.featured);
}

// Helper: min nightly rate across all units
export function getMinRate(complex: Complex): number {
  const rates = complex.units.flatMap((u) => u.rates.map((r) => r.perNight));
  return Math.min(...rates);
}

// Helper: get similar complexes (same category first, then others; excludes self)
export function getSimilarComplexes(current: Complex, count = 3): Complex[] {
  const sameCategory = complexes.filter(
    (c) => c.id !== current.id && c.category === current.category
  );
  const others = complexes.filter(
    (c) => c.id !== current.id && c.category !== current.category
  );

  // Featured first within each group
  const sort = (arr: Complex[]) =>
    [...arr].sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0));

  return [...sort(sameCategory), ...sort(others)].slice(0, count);
}

// Helper: find a unit by complex slug + unit id
export function getUnitByIds(slug: string, unitId: string): { complex: Complex; unit: Unit } | undefined {
  const complex = complexes.find((c) => c.slug === slug);
  if (!complex) return undefined;
  const unit = complex.units.find((u) => u.id === unitId);
  if (!unit) return undefined;
  return { complex, unit };
}

// Helper: get similar units for a unit page (other units in same complex + a unit from similar complexes)
export function getSimilarUnits(complex: Complex, currentUnit: Unit, count = 3): { complex: Complex; unit: Unit }[] {
  const results: { complex: Complex; unit: Unit }[] = [];

  // Other units in the same complex first
  for (const u of complex.units) {
    if (u.id !== currentUnit.id) results.push({ complex, unit: u });
  }

  // Fill remainder from similar complexes
  if (results.length < count) {
    const similar = getSimilarComplexes(complex, 6);
    for (const c of similar) {
      if (results.length >= count) break;
      if (c.units.length > 0) results.push({ complex: c, unit: c.units[0] });
    }
  }

  return results.slice(0, count);
}
